// El runner ListeningJourney reutiliza los campos { en, es } para { alemán, español }.
// El audio se sirve como `${audioBasePath}/listening-NN.mp3` según el `order`.

const q = (prompt: string, correct: string, wrong: string[], feedback: string): ListeningQuestion => ({
  prompt,
  options: [
    { label: correct, correct: true, feedback },
    ...wrong.map(label => ({ label, correct: false, feedback })),
  ],
})

// s = línea de transcripción (alemán, español); kw = palabra clave (alemán, español)
